import { sleep } from 'k6';
// Generated by grafana-k6 on 2026-09-11T16:51:00Z
import { SharedArray } from 'k6/data';
import { STORAGE_HOSTS, completeUpload, initUpload, uploadPart } from './common.js';
const videoData = new SharedArray('video-l30', () => {
  return open('../../tools/gen-video/fixtures/l30.mp4', 'b');
});

export const options = {
  hosts: STORAGE_HOSTS,
  scenarios: {
    large_file: {
      executor: 'per-vu-iterations',
      vus: 5,
      iterations: 1,
      maxDuration: '2h',
    },
  },
  thresholds: {
    'http_req_duration{name:presign}': ['p(95)<2000'],
    checks: ['rate>0.99'],
    http_req_failed: ['rate==0'], // zero 5xx
  },
};

const PART_SIZE = 64 * 1024 * 1024; // 64 MB

export default function () {
  const init = initUpload({
    filename: 'l30.mp4',
    sizeBytes: videoData.byteLength,
    contentType: 'video/mp4',
    strategy: 'multipart',
  });

  const uploadId = init.uploadId;
  const parts = init.parts || [];

  const etags = [];
  const partsExpected = init.partsExpected || parts.length;

  for (let i = 0; i < partsExpected; i++) {
    const start = i * PART_SIZE;
    const end = Math.min(start + PART_SIZE, videoData.byteLength);
    const chunk = videoData.slice(start, end);

    if (__ENV.KILL_AT_50 === 'true' && i >= partsExpected / 2) {
      console.log(`VU ${__VU} stopping at 50% to simulate crash`);
      return;
    }

    const partInfo = parts.find((p) => p.partNumber === i + 1);
    if (!partInfo) {
      throw new Error(`Missing part info for part ${i + 1}`);
    }

    const result = uploadPart(partInfo.url, chunk, i + 1);
    etags.push(result);
  }

  completeUpload(uploadId, etags);
  sleep(1);
}
